import 'package:zan/Core/Models/product_details_model.dart';import '../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../Core/Storage/Remote/api_service.dart';import '../../../../Core/Models/product_model.dart';import '../models/product_preview_entities.dart';Future<List<ProductPreviewEntities>> getDataProductIsFeatured() async {  final response = await DioHelper.getData(    path: ApiEndpoints.productFeatured,  );  if (response == null || response.data["data"] == null) {    return [];  }  return (response.data["data"] as List)      .map(        (item) => ProductPreviewEntities.fromProduct(          ProductModel.fromJson(item),        ),      )      .toList();}Future<List<ProductPreviewEntities>> getDataProductIsPopular() async {  final response = await DioHelper.getData(    path: ApiEndpoints.productPopular,  );  if (response == null || response.data["data"] == null) {    return [];  }  return (response.data["data"] as List)      .map(        (item) => ProductPreviewEntities.fromProduct(          ProductModel.fromJson(item),        ),      )      .toList();}Future<ProductDetailsModel> getProductsByID(int id) async {  final response = await DioHelper.postData(    data: id,    path: ApiEndpoints.productDetails,  );  if (response == null || response.data["data"] == null) {    return Future.value(null); // or return Future.value(ProductDetails());  }  return (response.data["data"]).map(    (item) => ProductDetailsModel.fromJson(      item,    ),  );}